/**
 * Nama berkas tanpa direktori, query, dan ekstensi, dalam huruf kecil.
 * Menyamakan "/kpr-assets/innara.jpg", "<uuid>/innara.webp", dan URL CDN
 * Supabase Storage menjadi satu kunci: "innara".
 */
const stem = (src: string) =>
  src.split("?")[0].split("/").pop()!.replace(/\.[a-z0-9]+$/i, "").toLowerCase()

/** Blur placeholder untuk sebuah URL gambar, dari mana pun ia dilayani. */
export const blurFor = (src?: string) => (src ? blurMap[stem(src)] : undefined)
